(()=>{
 const h=window.hb5,{tr,esc,state,companies,msps,company,record,person,money,users,signature}=h;
 const link=(hash,label)=>`<a href="#${esc(hash)}">${esc(label)}</a>`;
 const button=(action,label)=>`<button type="button" data-action="${action}">${esc(label)}</button>`;
 const select=(name,label,options,value)=>`<label>${esc(label)}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
 const policyName=v=>v==='required'?tr('Required','필수'):tr('Optional','선택');
 const eventName=v=>({review:tr('Review','검수'),issue:tr('Issue','발행'),assignment:tr('Assignment','담당자 지정'),'review-invalidated':tr('Review invalidated','검수 무효화')}[v]||v);
 const people=[['',tr('Unassigned · use actual actor','미지정 · 실제 처리자 기록')],...users.map(u=>[u.id,u.name])];
 const table=(heads,rows)=>`<div class="table-scroll" tabindex="0"><table><thead><tr>${heads.map(t=>`<th>${esc(t)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`;
 const title=(tag,name,lead)=>`<p class="eyebrow">${esc(tag)}</p><h1>${esc(name)}</h1><p class="lead">${esc(lead)}</p>`;
 const note=text=>`<p class="note">${esc(text)}</p>`;
 const facts=pairs=>`<dl class="facts">${pairs.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;
 const status=r=>r.status==='issued'?tr('Issued','발행 완료'):r.review&&r.review.signature===signature(r)?tr('Reviewed · not issued','검수 완료 · 미발행'):tr('Not issued · review pending','미발행 · 검수 대기');
 const actorText=a=>a?`${esc(a.name)}<small>${esc(a.id)} · ${esc(a.time)}</small>`:tr('Not performed','미처리');
 const tabs=c=>`<div class="tabs">${link('customer/'+c.id,tr('Customer overview','고객 개요'))}${link('contracts/'+c.id,tr('Contracts and renewal','계약·갱신'))}${link('register/'+c.id,tr('Monthly issuance','월별 발행 이력'))}</div>`;
 function register(){
  const visible=state.records.filter(r=>{const c=company(r.company);return (state.mode==='single'?c.id===state.company:c.msp===state.msp&&(state.company==='all'||c.id===state.company))&&(state.month==='all'||r.month===state.month)&&(state.status==='all'||r.status===state.status)&&(state.person==='all'||[r.issuer,r.reviewer,r.issue?.id,r.review?.id].includes(state.person));});
  const coptions=companies.filter(c=>c.msp===state.msp).map(c=>[c.id,c.name+' · '+c.id]);
  const filters=select('mode',tr('Operation','운영 형태'),[['msp',tr('MSP / multiple companies','MSP / 여러 회사')],['single',tr('Single company','단일 회사')]],state.mode)+select('msp','MSP',Object.entries(msps),state.msp)+select('company',tr('Company','회사'),state.mode==='single'?coptions:[['all',tr('All companies','전체 회사')],...coptions],state.company)+select('month',tr('Billing month','청구 월'),[['all',tr('All months','전체 월')],...['2026-08','2026-07','2026-06'].map(m=>[m,m])],state.month)+select('status',tr('Issuance','발행 여부'),[['all',tr('All statuses','전체 상태')],['issued',tr('Issued','발행 완료')],['draft',tr('Not issued','미발행')]],state.status)+select('person',tr('Assigned or actual actor','지정·실제 담당자'),[['all',tr('All people','전체 담당자')],...users.map(u=>[u.id,u.name])],state.person);
  let html=title('01 / BILLING REGISTER',tr('Monthly issuance register','월별 발행 이력'),tr('Start with the MSP, then inspect every company billed in each month — including unissued targets.','MSP별로 매월 청구 대상 회사와 발행 여부를 확인합니다. 미발행 회사도 목록에 남습니다.'));
  html+=`<form class="filters">${filters}<label class="check"><input type="checkbox" name="showPeople" ${state.showPeople?'checked':''}>${tr('Show issuer / reviewer columns','발행·검수 담당자 열 표시')}</label></form>`;
  html+=`<div class="summary"><strong>${esc(msps[state.msp])}</strong><span>${visible.length} ${tr('company-month targets','개 회사·월 청구 대상')}</span><span>${visible.filter(r=>r.status==='issued').length} ${tr('issued','발행 완료')} / ${visible.filter(r=>r.status!=='issued').length} ${tr('not issued','미발행')}</span>${link('policy/'+state.msp,tr('Assignment policy','담당자 지정 정책'))}</div>`;
  if(!visible.length)html+=note(tr('No targets match these filters. Clear filters to see other billing periods.','조건에 맞는 청구 대상이 없습니다. 조회 조건을 변경하세요.'));
  for(const month of ['2026-08','2026-07','2026-06']){
   const rs=visible.filter(r=>r.month===month);if(!rs.length)continue;
   html+=`<details open class="month-group"><summary>${month} <span>${rs.length} ${tr('companies','개 회사')} · ${rs.filter(r=>r.status==='issued').length} ${tr('issued','발행')}</span></summary>`;
   const heads=[tr('Company / ID','회사 / ID'),tr('Issuance','발행 여부'),tr('Issue date (UTC)','발행일 (UTC)'),tr('Invoice / amount','인보이스 / 금액')];
   if(state.showPeople)heads.push(tr('Issuer / actual','발행 담당 / 실제'),tr('Reviewer / actual','검수 담당 / 실제'));
   heads.push(tr('Details','상세'));
   html+=table(heads,rs.map(r=>{const c=company(r.company);const cells=[link('customer/'+c.id,c.name)+`<small>${esc(c.id)} · ${esc(c.currency)}</small>`,esc(status(r)),r.issuedAt?r.issuedAt.slice(0,10):'—',(r.number?esc(r.number):tr('No invoice yet','인보이스 미생성'))+`<small>${esc(money(r.sale,r.currency))}${r.status==='draft'?' · '+tr('draft','초안'):''}</small>`];if(state.showPeople)cells.push(`${esc(person(r.issuer))}<small>${tr('Actual','실제')}: ${r.issue?esc(r.issue.name):tr('Not issued','미발행')}</small>`,`${esc(person(r.reviewer))}<small>${tr('Actual','실제')}: ${r.review?esc(r.review.name):tr('Review pending','검수 대기')}</small>`);cells.push(link('document/'+r.id,tr('Open record','기록 보기')));return cells;}));html+='</details>';
  }
  return html+note(tr('Amounts are separate by currency. Dates are UTC. Current company names link to profiles; issued documents retain historical snapshots. All data is synthetic.','통화별 금액은 합산하지 않습니다. 시각은 UTC입니다. 고객명은 현재 고객 상세로 연결되며 발행 문서는 당시 정보를 보존합니다. 모두 합성 예시입니다.'));
 }
 function customer(id){
  const c=company(id);if(!c)return note(tr('Customer not found.','고객을 찾을 수 없습니다.'));
  return title('02 / CUSTOMER',c.name,tr('Customer identity and contract context behind every monthly invoice.','월별 청구의 기준이 되는 고객 정보와 계약을 확인합니다.'))+tabs(c)+facts([[tr('Company ID / MSP','회사 ID / MSP'),c.id+' / '+msps[c.msp]],[tr('Legal name','법인명'),c.legal],[tr('Country / tax identifier','국가 / 세금 식별번호'),c.country+' / '+c.tax],[tr('Billing address','청구 주소'),c.address],[tr('Billing contact','정산 담당자'),c.contact+' / '+c.email],[tr('Currency / payment terms','통화 / 지급 조건'),c.currency+' / '+c.terms],[tr('Contract / renewal','계약 / 갱신일'),c.contract+' / '+c.renewal],[tr('Termination notice deadline','해지 통지 기한'),c.notice]])+`<h2>${tr('Linked billing sources','연결된 청구 수집원')}</h2>`+table([tr('Account scope','계정 범위'),tr('Attribution','비용 귀속'),tr('Contract','계약')],[[esc(c.account),esc(c.id)+' · '+tr('Company allocation','회사 배부'),esc(c.version)]])+note(tr('Current profile, not a historical invoice snapshot. Contact maintenance and account assignment are design data; no customer system is connected.','현재 고객 정보이며 과거 인보이스의 스냅샷과 구분됩니다. 연락처·계정 귀속은 시안 데이터이며 고객 시스템과 연결되지 않았습니다.'));
 }
 function contracts(id){
  const c=company(id);if(!c)return note(tr('Contract customer not found.','계약 고객을 찾을 수 없습니다.'));
  const renewal=state.renewals.filter(x=>x.company===id);
  return title('03 / CONTRACTS',tr('Contract lifecycle and effective versions','계약 유지·갱신과 적용 버전'),c.name+' · '+c.id)+tabs(c)+facts([[tr('Active agreement','유효 계약'),c.contract],[tr('Effective version','적용 버전'),c.version],[tr('Current term','현재 계약 기간'),'2026-01-01 → '+c.renewal],[tr('Renewal / notice deadline','갱신 / 통지 기한'),c.renewal+' / '+c.notice],[tr('Billing conditions','청구 조건'),c.currency+' / '+c.terms],[tr('Selling rule','판매 요율'),c.rate]])+`<h2>${tr('Version register','계약 버전 이력')}</h2>`+table([tr('Version','버전'),tr('Effective from','적용 시작'),tr('Status','상태'),tr('Billing impact','청구 영향')],[[esc(c.version),'2026-01-01',tr('Active synthetic contract','유효 예시 계약'),tr('Historical issued months remain pinned','과거 발행 월의 버전 고정')],...renewal.map(x=>[esc(x.id),esc(x.effective),tr('Renewal draft · approval pending','갱신 초안 · 승인 대기'),esc(x.reason)])])+`<form class="action-form"><label>${tr('Future effective date','향후 적용 시작일')}<input type="date" name="effective" value="${c.renewal}"></label><label>${tr('Change / renewal reason','변경·갱신 사유')}<input name="renewalReason" maxlength="160"></label>${button('renewal',tr('Save renewal draft · demo','갱신 초안 저장 · 시연'))}</form>`+note(tr('Draft only: saving does not activate new prices or change issued documents. Activation, signed contract upload and overlapping-term validation require the future contract service.','초안 저장은 새 요율을 활성화하거나 발행 문서를 변경하지 않습니다. 계약 활성화·서명 계약 업로드·적용 기간 중복 검증은 향후 계약 서비스 연결이 필요합니다.'));
 }
 function documentView(id){
  const r=record(id);if(!r)return note(tr('Record not found.','기록을 찾을 수 없습니다.'));
  const c=company(r.company);
  return title('04 / ISSUANCE RECORD',r.number||tr('Unissued billing target','미발행 청구 대상'),c.name+' / '+c.id+' / '+r.month)+`<div class="tabs">${link('register/'+c.id,tr('Company monthly list','회사별 월 이력'))}${link('customer/'+c.id,tr('Customer detail','고객 상세'))}${link('contracts/'+c.id,tr('Contract','계약'))}${link('process/'+r.id,tr('Review / issuance workspace','검수·발행 작업'))}</div>`+facts([[tr('Target ID','청구 대상 ID'),r.id],[tr('Status','상태'),status(r)],[tr('Billing month / issue date','청구 월 / 발행일'),r.month+' / '+(r.issuedAt||'—')],[tr('Invoice total','청구 총액'),money(r.sale,r.currency)],[tr('Pinned contract / calculation','고정 계약 / 계산 버전'),r.contract+' / C'+r.calculation],[tr('Assignment policy snapshot','담당자 정책 스냅샷'),'P'+r.policy.version+' · '+tr('Issuer','발행')+' '+policyName(r.policy.issuer)+' / '+tr('Reviewer','검수')+' '+policyName(r.policy.reviewer)]])+table([tr('Role','역할'),tr('Designated owner','지정 담당자'),tr('Actual actor / time (UTC)','실제 처리자 / 시각 (UTC)')],[[tr('Reviewer','검수'),esc(person(r.reviewer)),actorText(r.review)],[tr('Issuer','발행'),esc(person(r.issuer)),actorText(r.issue)]])+`<h2>${tr('Retained action history','보존된 처리 이력')}</h2>`+table([tr('Action','작업'),tr('Actor','처리자'),tr('Time (UTC)','시각 (UTC)'),tr('Evidence','근거')],r.events.length?r.events.map(e=>[esc(eventName(e.kind)),esc(e.name)+'<small>'+esc(e.id)+'</small>',esc(e.time),esc(e.detail)]):[[tr('No completed action','완료 작업 없음'),'—','—',tr('Review has not happened','검수 미수행')]])+note(tr('Issued snapshots are read-only. Changing the viewing user or current policy never changes historical actor names. No correction/reissue exists for this sample; the earlier correction example is separate.','발행 스냅샷은 읽기 전용입니다. 조회 사용자·현재 정책 변경은 과거 처리자 이름을 바꾸지 않습니다. 이 예시에는 정정·재발행 건이 없으며 기존 정정 시나리오는 별도 사례입니다.'));
 }
 function policy(id){
  const msp=msps[id]?id:state.msp,p=state.policies[msp];
  const options=[['optional',tr('Optional — actual actor if unassigned','선택 — 미지정 시 실제 처리자')],['required',tr('Required — assign before action','필수 — 작업 전 담당자 지정')]];
  return title('05 / POLICY',tr('Issuer and reviewer assignment policy','발행·검수 담당자 지정 정책'),msps[msp]+' / P'+p.version)+note(tr('Design default: optional issuer, required reviewer. Choose each independently. Review itself remains mandatory regardless of assignment policy.','시안 기본값: 발행 담당 선택·검수 담당 필수. 각각 변경할 수 있습니다. 담당자 지정이 선택이어도 검수 절차 자체는 필수입니다.'))+`<form class="action-form">${select('issuerPolicy',tr('Issuer assignment','발행 담당자 지정'),options,p.issuer)}${select('reviewerPolicy',tr('Reviewer assignment','검수 담당자 지정'),options,p.reviewer)}${button('policy',tr('Save policy · demo','정책 저장 · 시연'))}</form>`+table([tr('Setting','설정'),tr('Before processing','처리 전'),tr('Successful processing','처리 성공 시')],[[tr('Optional / unassigned','선택 / 미지정'),tr('No completed actor displayed','완료 처리자 이름 없음'),tr('Record logged-in name + user ID + time','로그인 이름·사용자 ID·시각 기록')],[tr('Required / unassigned','필수 / 미지정'),tr('Action blocked until assigned','담당자 지정 전 작업 차단'),tr('No false completed history','허위 완료 이력 생성 없음')],[tr('Assigned to another person','타인 지정'),tr('Only designated actor may execute in this demo','이 시안은 지정된 사용자만 작업 가능'),tr('Actual actor remains distinct from assignment','지정과 실제 처리 기록 분리')],[tr('Policy changed','정책 변경'),tr('Open drafts require review again','미발행 초안 재검수 필요'),tr('Issued policy and actors remain unchanged','발행 당시 정책·처리자 유지')]])+`<h2>${tr('Policy change log','정책 변경 이력')}</h2>`+table([tr('Version','버전'),tr('Actor','변경자'),tr('Time','시각')],state.policyEvents.filter(e=>e.msp===msp).map(e=>['P'+e.version,esc(e.name)+' / '+esc(e.id),esc(e.time)]))+note(tr('Policy applies to this MSP only. In-memory simulation; no authorization service or production role checks are implemented.','해당 MSP에만 적용됩니다. 메모리 내 시연이며 실제 인증·권한 서비스와 연결되지 않았습니다.'));
 }
 function process(id){
  const r=record(id);if(!r)return note(tr('Record not found.','기록을 찾을 수 없습니다.'));
  const c=company(r.company),p=r.policy;
  const gates=[tr('Reviewer assignment','검수 담당 지정')+': '+(p.reviewer==='required'&&!r.reviewer?tr('Required · missing','필수 · 미지정'):tr('Ready','조건 충족')),tr('Issuer assignment','발행 담당 지정')+': '+(p.issuer==='required'&&!r.issuer?tr('Required · missing','필수 · 미지정'):tr('Ready','조건 충족')),tr('Review','검수')+': '+status(r)];
  return title('06 / CONTROLLED ACTION',tr('Review and issue','검수·발행 처리'),c.name+' / '+c.id+' / '+r.month+' / '+money(r.sale,r.currency))+`<div class="tabs">${link('document/'+r.id,tr('Document and actor history','문서·담당자 이력'))}${link('policy/'+c.msp,tr('Assignment policy','담당자 지정 정책'))}</div>`+`<div class="summary">${gates.map(g=>'<span>'+esc(g)+'</span>').join('')}</div>`+facts([[tr('Draft version','초안 버전'),'D'+r.revision],[tr('Pinned contract','적용 계약'),r.contract],[tr('Calculation / evidence','계산 / 근거'),'C'+r.calculation+' / '+(r.sourceValid?tr('Synthetic checks ready','합성 검증 준비'):tr('Evidence mismatch','근거 불일치'))],[tr('Policy','정책'),'P'+p.version+' / '+policyName(p.issuer)+' / '+policyName(p.reviewer)]])+(r.status==='issued'?note(tr('Issued: this snapshot is locked. Repeating issue cannot create another invoice.','발행 완료: 스냅샷이 잠겼습니다. 발행을 반복해도 새 인보이스를 만들지 않습니다.')):`<form class="action-form">${select('issuerAssigned',tr('Designated issuer','지정 발행 담당자'),people,r.issuer)}${select('reviewerAssigned',tr('Designated reviewer','지정 검수 담당자'),people,r.reviewer)}${button('assign',tr('Save assignments','담당자 지정 저장'))}</form><form class="action-form">${select('evidence',tr('Evidence condition · simulation','근거 상태 · 시연'),[['valid',tr('Validated synthetic evidence','검증된 합성 근거')],['invalid',tr('Mismatch / block review','불일치 / 검수 차단')]],r.sourceValid?'valid':'invalid')}${button('evidence',tr('Apply evidence change','근거 변경 적용'))}</form>`)+`<div class="actions">${button('review',tr('Complete review · demo','검수 완료 · 시연'))}${button('issue',tr('Issue once · demo','인보이스 발행 · 시연'))}</div>`+table([tr('Role','역할'),tr('Designated','지정'),tr('Actual successful actor','실제 성공 처리자')],[[tr('Reviewer','검수'),esc(person(r.reviewer)),actorText(r.review)],[tr('Issuer','발행'),esc(person(r.issuer)),actorText(r.issue)]])+note(tr('Successful actions snapshot the simulated signed-in actor, not the current viewer. Changed assignments, evidence or policy invalidate draft review and preserve prior events. Same-person review/issue is allowed in this demo; segregation-of-duties policy is not assumed.','성공한 작업은 조회자가 아닌 시연 로그인 사용자를 기록합니다. 담당자·근거·정책 변경 시 초안 검수는 무효화하고 이전 이력은 보존합니다. 이 시안은 동일인의 검수·발행을 허용하며 직무 분리 정책을 임의로 가정하지 않습니다.'));
 }
 Object.assign(h,{link,button,select,people,table,title,note,facts,status,views:{register,customer,contracts,document:documentView,policy,process}});
})();
